def maxNumEdgesToRemove(n: int, edges: list[list[int]]) -> int:
    parent_a = list(range(n + 1))
    parent_b = list(range(n + 1))
    def find(p, i):
        if p[i] == i: return i
        p[i] = find(p, p[i])
        return p[i]
    def union(p, u, v):
        ru, rv = find(p, u), find(p, v)
        if ru == rv: return False
        p[ru] = rv
        return True
    used = 0
    comp_a = comp_b = n
    # Process type 3 edges first
    for t, u, v in edges:
        if t == 3:
            ua = union(parent_a, u, v)
            ub = union(parent_b, u, v)
            if ua or ub:
                used += 1
                comp_a -= 1
                comp_b -= 1
    for t, u, v in edges:
        if t == 1:
            if union(parent_a, u, v):
                used += 1
                comp_a -= 1
        elif t == 2:
            if union(parent_b, u, v):
                used += 1
                comp_b -= 1
    if comp_a == 1 and comp_b == 1:
        return len(edges) - used
    return -1

